///
/// A floor written before this repair (no `bound_repository_lineage`/`bound_project_identity` field at all) is
/// treated exactly like a mismatch: reported, never silently honoured — the caller's own reconstruction fallback
/// (`PolicySet::load`, AR82-C2/AR84-C1) then re-derives what THIS repository's current native structure needs, so
/// the obligation is not simply dropped either way.
pub fn read_project_adoption_floor(root: &Path) -> AdoptionFloor {
    let path = root.join(PROJECT_ADOPTION_FLOOR_PATH);
    if !path.exists() {
        return AdoptionFloor::default();
    }
    let binding = crate::t2::verify_file(root, PROJECT_ADOPTION_FLOOR_PATH);
    if !binding.is_verified() {
        return AdoptionFloor {
            rules: vec![],
            finding: Some(json!({
                "policy": "PROJECT_ADOPTION_FLOOR", "key": "floor", "value": Value::Null, "source": PROJECT_ADOPTION_FLOOR_PATH,
                "kernel_value": Value::Null, "t2": binding.to_value(),
                "reason": format!(
                    "{PROJECT_ADOPTION_FLOOR_PATH} exists but its T2 seal does not verify (binding {}): the native-\
                     layout path floor this project's onboarding derived is NOT being applied, so a widening of a \
                     native source/test directory's class would not be refused until this is investigated and the \
                     floor is restored from version control or re-derived through a fresh governed onboarding \
                     (P2-HO-0056 §3, OD-P2-08 §2)",
                    binding.code()
                ),
            })),
            ..Default::default()
        };
    }
    let Ok(doc) = crate::util::read_json(&path) else {
        // Verified seal, unreadable content -- pre-existing edge case unrelated to AR84-C3, unchanged: an empty,
        // unflagged floor.
        return AdoptionFloor::default();
    };
    // AR84-C3: the seal verifying is necessary but not sufficient -- it must also be bound to THIS repository's
    // own git lineage (never its filesystem path -- see `repository_lineage_id`'s own doc on why: a legitimate
    // `git clone` to a different path/machine must still verify, and does, because a clone shares its origin's
    // root commit exactly).
    let lineage = repository_lineage_id(root);
    let bound = doc.get("bound_repository_lineage").and_then(|v| v.as_str());
    if bound != Some(lineage.as_str()) {
        return AdoptionFloor {
            rules: vec![],
            finding: Some(json!({
                "policy": "PROJECT_ADOPTION_FLOOR", "key": "floor", "value": Value::Null, "source": PROJECT_ADOPTION_FLOOR_PATH,
                "kernel_value": Value::Null,
                "reason": format!(
                    "{PROJECT_ADOPTION_FLOOR_PATH} verifies its T2 seal, but its bound repository lineage ({}) does \
                     not match this repository's own git lineage ({lineage:?}): the seal proves only that SOME \
                     `gov` operation on this machine once wrote these bytes, never that it wrote them FOR THIS \
                     project (AR84-C3) -- a validly-sealed floor authored for a different repository (or written \
                     before this identity binding existed at all) is not honoured here. The native-layout path \
                     floor this project's own onboarding derived is NOT being applied until this is investigated \
                     and the floor is restored from version control or re-derived through a fresh governed \
                     onboarding (P2-HO-0056 §3, OD-P2-08 §2/§5)",
                    bound.map(|b| format!("{b:?}")).unwrap_or_else(|| "none -- no binding field at all".into())
                ),
            })),
            ..Default::default()
        };
    }
    // AR86-C1/C2/C3: lineage matching is necessary but STILL not sufficient -- see `FloorIdentity`'s own doc for
    // why (a clone shares lineage by construction; any subdirectory used to report it; neither carries a
    // checkout-local identity or sequence). Checked against the anchor OUTSIDE this document, which an ordinary
    // copy of the document alone (every AR86-C1/C2/C3/C4 reproduction) cannot bring with it.
    let doc_identity = doc.get("bound_project_identity").and_then(|v| v.as_str());
    let doc_sequence = doc.get("floor_sequence").and_then(|v| v.as_u64()).unwrap_or(0);
    if let Err(reason) = FloorIdentity::reconcile(root, doc_identity, doc_sequence) {
        return AdoptionFloor {
            rules: vec![],
            finding: Some(json!({
                "policy": "PROJECT_ADOPTION_FLOOR", "key": "floor", "value": Value::Null, "source": PROJECT_ADOPTION_FLOOR_PATH,
                "kernel_value": Value::Null,
                "reason": format!(
                    "{PROJECT_ADOPTION_FLOOR_PATH} verifies its T2 seal and its git lineage matches, but {reason} \
                     (AR86-C1/C2/C3, OD-P2-08 §5). The native-layout path floor this project's own onboarding \
                     derived is NOT being applied until this is investigated and the floor is restored from \
                     version control or re-derived through a fresh governed onboarding (P2-HO-0056 §3, \
                     OD-P2-08 §2/§5)"
                ),
            })),
            ..Default::default()
        };
    }
    // P2-AR-0091 (AR90-C5/C6): `bound_cit`, where present, is now GATED rather than merely recorded. FloorIdentity
    // above is what authenticates every floor, including onboarding's own first write, which has no transaction to
    // name -- so an ABSENT `bound_cit` is accepted unconditionally, exactly as before this check existed. Where
    // PRESENT, it must name a CIT this project's own record store currently reads as EXECUTING or COMMITTED.
    // EXECUTING is accepted (not just COMMITTED) because a `reclassify_adoption_floor` execution re-reads its OWN
    // just-written floor from inside the SAME `cit execute`, before its final seal (`propagation::apply`,
    // `tools::generate_registry`, `adapters::generate` and `memory::indexer::rebuild` all reload `PolicySet` while
    // the record is still EXECUTING) -- refusing that self-reference would break a transaction's own legitimate
    // write to itself. This closes AR90-C6's specific residual as defence in depth alongside the `manifest_paths`/
    // snapshot fix ([`crate::cit`]'s own doc): a floor whose write a ROLLED_BACK (or otherwise absent) record
    // denies ever committing is refused here even if some other path let the bytes survive. It also closes AR90-C5
    // (a `bound_cit` naming a transaction this project's own store has never heard of at all, `None` here, was
    // previously honoured unconditionally).
    // **P2-AR-0093 (AR92-D1) — named precisely, not oversold.** `RecordStore::load` below parses the record file
    // straight off disk: it performs no T2/`cit::binding` verification, although `cit` is itself one of
    // `t2::SEALED_RECORD_TYPES`, and the match on `cit_id` below is on ID ALONE -- it never consults
    // `cit::binding`'s own `writes_sha256` to confirm the named transaction's WRITES actually covered these
    // exact bytes. This gate is DETECTION and defence in depth against an accidental mismatch (a rolled-back or
    // never-existed transaction id, AR90-C5/C6, both closed and re-verified below) -- it is NOT proof-grade
    // binding authority, and must never be described or relied on as such: an actor able to write project files
    // (the same actor `FloorIdentity` above is the sole authenticator against) can plant any `CIT-xxxx` id this
    // project's own store happens to read as EXECUTING/COMMITTED, whatever that transaction actually wrote.
    // `FloorIdentity` remains the one authenticator AR88/AR90/AR92's HIGH findings are closed by; this check adds
    // nothing to that boundary.
    if let Some(cit_id) = doc.get("bound_cit").and_then(|v| v.as_str()) {
        let status = crate::records::RecordStore::load(root)
            .get(cit_id)
            .map(|r| r.get("cit_status"));
        if !matches!(status.as_deref(), Some("EXECUTING") | Some("COMMITTED")) {
            return AdoptionFloor {
                rules: vec![],
                finding: Some(json!({
                    "policy": "PROJECT_ADOPTION_FLOOR", "key": "floor", "value": Value::Null, "source": PROJECT_ADOPTION_FLOOR_PATH,
                    "kernel_value": Value::Null,
                    "reason": format!(
                        "{PROJECT_ADOPTION_FLOOR_PATH} verifies its T2 seal, its git lineage and its checkout \
                         identity/sequence, but names bound_cit {cit_id:?}, whose record in this project's own \
                         store {} (P2-AR-0091, AR90-C5/C6): FloorIdentity alone authenticates that THIS checkout \
                         wrote these bytes; bound_cit additionally claims WHICH governed transaction authorised \
                         them, and this project's own record store does not confirm that claim. The native-layout \
                         path floor this project's own onboarding derived is NOT being applied until this is \
                         investigated and the floor is restored from version control or re-derived through a \
                         fresh governed onboarding (P2-HO-0056 §3, OD-P2-08 §2/§5)",
                        status
                            .as_deref()
                            .map(|s| format!("reads {s:?}"))
                            .unwrap_or_else(|| "does not exist".to_string())
                    ),
                })),
                ..Default::default()
            };
        }
    }
    let rules = doc
        .get("floor")
        .and_then(|f| f.as_array().cloned())
        .unwrap_or_default();
    // AR86-C6: this floor is now fully authenticated (seal, lineage, checkout identity and sequence all agree) --
    // remember its rules as this checkout's own last-known-good, so a LATER reconstruction (triggered only once
    // the authenticated record has already become untrustworthy) is never derived from a weaker set than what was
    // last established here.
    FloorIdentity::remember_rules(root, &rules);
    // P2-AR-0093 (AR92-C4): disclose a bootstrap-adopt, never silently -- read off the durable
    // `bootstrap_adopted` flag (`FloorIdentityState`'s own doc explains why NOT a transient, in-process signal).
    // `other_live_claim` (inside the `reconcile` call above, which already returned Ok) already refuses every
    // case this machine holds ANY prior entry for, so a `true` flag here names a genuinely never-before-seen
    // path when it was SET: a portable clone (P2-ADJ-0002) -- the only surviving case since P2-AR-0096 deleted
    // `gov floor-reanchor`, the other way this branch used to be reached. Never a genuine `gov init`/`gov adopt`
    // onboarding, which always writes through `FloorIdentity::advance` (`bootstrap: false`) instead.
    let bootstrap_disclosure = FloorIdentity::read_full(root)
        .filter(|s| s.bootstrap_adopted)
        .map(|_| {
            json!({
                "event": "PROJECT_ADOPTION_FLOOR_BOOTSTRAPPED",
                "project_identity": doc_identity,
                "canonical_path": canonical_path_string(root),
                "reason": format!(
                    "this checkout's local ledger for bound_project_identity {doc_identity:?} was established by \
                     adopting {PROJECT_ADOPTION_FLOOR_PATH}'s own claim (a portable clone), never by this \
                     checkout's own onboarding -- other_live_claim already refuses every case this machine holds \
                     a prior entry for, P2-AR-0093"
                ),
            })
        });
    AdoptionFloor { rules, finding: None, bootstrap_disclosure }
}

